import os
for key in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS','NUMEXPR_NUM_THREADS'):
    os.environ[key]='1'
os.environ['PYTHONDONTWRITEBYTECODE']='1'
os.nice(max(0,19-os.getpriority(os.PRIO_PROCESS,0)))
import argparse
import base64
import hashlib
import json
import platform
import sys
import time
import zlib
from pathlib import Path,PurePosixPath
sys.dont_write_bytecode=True


def require(ok,msg):
    if not ok: raise ArithmeticError(msg)


def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()


def unpack(root):
    payload=zlib.decompress(base64.b85decode(PAYLOAD))
    require(hashlib.sha256(payload).hexdigest()==PAYLOAD_SHA256,'payload digest')
    bundle=json.loads(payload)
    require(set(bundle)=={'files','hashes','config'},'payload schema')
    require(set(bundle['files'])==set(bundle['hashes']),'complete embedded manifest')
    for name,content in bundle['files'].items():
        parts=PurePosixPath(name)
        require(not parts.is_absolute() and '..' not in parts.parts,'safe embedded path')
        require(hashlib.sha256(content.encode()).hexdigest()==bundle['hashes'][name],'embedded digest '+name)
        dest=root/name;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content)
        require(sha(dest)==bundle['hashes'][name],'extraction readback '+name)
    return bundle


def write_readback(path,obj):
    path.write_text(json.dumps(obj,indent=2,sort_keys=True,allow_nan=False)+'\n')
    require(json.loads(path.read_text())==obj,'JSON receipt readback')


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--dimension',choices=['5', '9', '11', '12', '13', '15', '16', '17', '18', '20', '21', 'all'],default='all')
    ap.add_argument('--workdir',required=True)
    args=ap.parse_args();start=time.monotonic();root=Path(args.workdir).absolute()
    require(not root.is_symlink(),'destination must not be a symlink')
    if root.exists():require(root.is_dir() and not any(root.iterdir()),'destination must be empty')
    else:root.mkdir(parents=True)
    bundle=unpack(root);sys.path.insert(0,str(root/'sources'))
    import flint,numpy,scipy
    from flint import arb,ctx
    import spectral_certify as spectral
    from analytic_bounds import shape_bounds,dirichlet_transfer,fixed_fields
    from boundary_certify import certify
    from coupled_bounds import compute,gates
    from negative_controls import validate_center,run_controls
    import check_identities
    from second_interval import verify as second_verify
    for module_name in ('spectral_certify','analytic_bounds','refine_boundary','boundary_certify',
                        'coupled_bounds','negative_controls','check_identities','second_interval'):
        require(Path(sys.modules[module_name].__file__).resolve()==(root/'sources'/f'{module_name}.py').resolve(),
                'isolated module binding '+module_name)
    ctx.threads=1
    check_identities.main(root/'identity_receipt.json')
    program_sha=sha(Path(__file__).resolve())
    dimensions=[5, 9, 11, 12, 13, 15, 16, 17, 18, 20, 21] if args.dimension=='all' else [int(args.dimension)]
    records={};failed=[]
    for n in dimensions:
        ds=time.monotonic();out=root/f'n{n}';out.mkdir()
        try:
            cfg=bundle['config'][str(n)]
            require(set(cfg)=={'center','R','S','grid','modes','bits','sigma','radius'},'dimension config schema')
            path=root/cfg['center'];data=json.loads(path.read_text());validate_center(data)
            require(data['n']==n,'input dimension binding')
            print(json.dumps({'stage':'start_dimension','n':n,'center_sha256':sha(path)}),flush=True)
            saved=sys.argv
            try:
                sys.argv=['spectral_certify.py','--center',str(path),'--output',str(out/'spectral.json')]
                spec=spectral.main()
            finally:sys.argv=saved
            require(spec['centre_sha256']==sha(path),'spectral center binding')
            ctx.prec=cfg['bits'];ctx.threads=1
            R=arb(cfg['R']);S=arb(cfg['S'])
            mom,bd=certify(data,R,S,cfg['grid'],cfg['modes'])
            bd.update(status='BOUNDARY_MOMENTS_ENCLOSED',n=n,center_sha256=sha(path),bits=ctx.prec)
            write_readback(out/'boundary.json',bd)
            print(json.dumps({'stage':'boundary_complete','n':n,'seconds':time.monotonic()-ds}),flush=True)
            ctx.prec=512
            s=shape_bounds(data,arb(cfg['R']))
            tr=dirichlet_transfer(s,arb(spec['bounds']['L2_inverse_full']))
            field=fixed_fields(data,s)
            values=compute(data,s,tr,field,mom,arb(cfg['radius']),arb(cfg['sigma']))
            gates(values)
            negative=run_controls(data,spec,s,tr,field,mom,values,R,S,cfg['grid'],cfg['modes'])
            for key in ('radius','sigma'):
                bad=cfg.copy();bad[key]='0'
                try:second_verify(data,s,tr,field,mom,bad,values)
                except ArithmeticError as exc:
                    negative.append({'name':'second interval zero '+key,'status':'REJECTED','reason':str(exc)})
                else:raise ArithmeticError('second interval negative control accepted')
            # Recompute the final chain after every negative injection.
            values=compute(data,s,tr,field,mom,arb(cfg['radius']),arb(cfg['sigma']))
            gates(values)
            second=second_verify(data,s,tr,field,mom,cfg,values)
            write_readback(out/'second_interval.json',second)
            write_readback(out/'negative_controls.json',negative)
            analytic={'shape':{k:v.str(55) for k,v in s.items()},
                      'transfer':{k:v.str(55) for k,v in tr.items()},
                      'fixed_fields':{k:v.str(55) for k,v in field.items()}}
            write_readback(out/'analytic.json',analytic)
            artifacts={str(p.relative_to(root)):sha(p) for p in [path,out/'spectral.json',out/'boundary.json',out/'analytic.json',out/'negative_controls.json',out/'second_interval.json',root/'identity_receipt.json']}
            artifacts.update({name:sha(root/name) for name in bundle['files'] if name.startswith('sources/')})
            rec={'status':'PROVED','n':n,'scope':'Numerical certificate plus analytic lemmas in PROOF_PACKAGE.md; not a proof-assistant formalization',
                 'old_coupled_inverse_used':False,'external_models_used':False,
                 'all_final_gates_recomputed_in_one_process':True,'verifier_sha256':program_sha,
                 'second_scalar_interval_pass':True,
                 'payload_sha256':PAYLOAD_SHA256,'center_sha256':sha(path),'configuration':cfg,
                 'bounds':{k:v.str(55) for k,v in values.items()},'L2_inverse':spec['bounds']['L2_inverse_full'],
                 'spectral_states':spec['basis_size'],'negative_tests':len(negative),
                 'seconds':time.monotonic()-ds,'artifacts':artifacts,
                 'environment':{'python':platform.python_version(),'python_flint':flint.__version__,
                                'numpy':numpy.__version__,'scipy':scipy.__version__,
                                'sympy':sys.modules['sympy'].__version__,'mpmath':sys.modules['mpmath'].__version__,
                                'arb_threads':ctx.threads,'nice':os.getpriority(os.PRIO_PROCESS,0),
                                'cpu_affinity':sorted(os.sched_getaffinity(0))}}
            for name,digest in artifacts.items():require(sha(root/name)==digest,'artifact readback '+name)
            write_readback(out/'VERIFICATION_RECEIPT.json',rec)
            records[str(n)]={'status':'PROVED','receipt':str((out/'VERIFICATION_RECEIPT.json').relative_to(root)),
                             'receipt_sha256':sha(out/'VERIFICATION_RECEIPT.json'),'seconds':rec['seconds']}
            print('PROVED n='+str(n)+' receipt='+str(out/'VERIFICATION_RECEIPT.json'),flush=True)
        except Exception as exc:
            rec={'status':'NOT_PROVED','n':n,'exception':type(exc).__name__,'reason':str(exc),
                 'seconds':time.monotonic()-ds,'verifier_sha256':program_sha}
            write_readback(out/'FAILURE_RECEIPT.json',rec)
            records[str(n)]=rec;failed.append(n)
            print(json.dumps(rec),flush=True)
    result={'status':'PROVED' if not failed else 'NOT_ALL_PROVED','dimensions':records,
            'verifier_sha256':program_sha,'payload_sha256':PAYLOAD_SHA256,'seconds':time.monotonic()-start}
    write_readback(root/'VERIFICATION_RECEIPT.json',result)
    if failed:raise SystemExit(1)
    print('PROVED dimensions='+','.join(map(str,dimensions)),flush=True)


if __name__=='__main__':
    try:main()
    except Exception as exc:
        print('NOT_PROVED '+type(exc).__name__+': '+str(exc),file=sys.stderr,flush=True)
        raise SystemExit(1)
